import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import session from 'express-session';

const app = express();
app.use(express.json());
app.use(session({ secret: process.env.SESSION_SECRET || 'dev-secret', resave: false, saveUninitialized: false }));

const pool = new Pool({ connectionString: process.env.DATABASE_URL });

// Middleware: check auth
function requireAuth(req, res, next) {
  if (!req.session.userId) return res.status(401).json({ error: 'unauthorized' });
  next();
}

// User profile update - supports partial updates
app.put('/api/users/:id/profile', requireAuth, async (req, res) => {
  const userId = req.params.id;
  if (req.session.userId !== userId && req.session.role !== 'admin') {
    return res.status(403).json({ error: 'forbidden' });
  }

  const allowedFields = ['display_name', 'bio', 'avatar_url', 'theme_preference'];
  const updates = [];
  const values = [];
  let paramIdx = 1;

  for (const [key, value] of Object.entries(req.body)) {
    if (allowedFields.includes(key)) {
      updates.push(`${key} = $${paramIdx}`);
      values.push(value);
      paramIdx++;
    }
  }

  if (updates.length === 0) return res.status(400).json({ error: 'no valid fields' });
  values.push(userId);

  const query = `UPDATE users SET ${updates.join(', ')} WHERE id = $${paramIdx}`;
  await pool.query(query, values);
  res.json({ success: true });
});

// Report generation endpoint - vulnerable to path traversal
app.get('/api/reports/generate', requireAuth, async (req, res) => {
  const { template, format, quarter } = req.query;
  const templatePath = `./templates/reports/${template}`;

  // Read template file
  const fs = await import('fs/promises');
  try {
    const content = await fs.readFile(templatePath, 'utf-8');
    const result = await pool.query(
      'SELECT * FROM quarterly_metrics WHERE quarter = $1 AND org_id = $2',
      [quarter, req.session.orgId]
    );

    // Simple template rendering
    let rendered = content;
    for (const [key, val] of Object.entries(result.rows[0] || {})) {
      rendered = rendered.replaceAll(`{{${key}}}`, String(val));
    }

    res.setHeader('Content-Type', format === 'html' ? 'text/html' : 'text/plain');
    res.send(rendered);
  } catch (err) {
    res.status(404).json({ error: 'template not found' });
  }
});

// Webhook delivery with HMAC signing
app.post('/api/webhooks/deliver', requireAuth, async (req, res) => {
  const { event_type, payload, target_url } = req.body;
  const hmac = crypto.createHmac('sha256', process.env.WEBHOOK_SECRET || 'whsec_default');
  hmac.update(JSON.stringify(payload));
  const signature = hmac.digest('hex');

  try {
    const response = await fetch(target_url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-Webhook-Signature': signature,
        'X-Event-Type': event_type
      },
      body: JSON.stringify(payload)
    });

    await pool.query(
      'INSERT INTO webhook_deliveries (event_type, target_url, status_code, delivered_at) VALUES ($1, $2, $3, NOW())',
      [event_type, target_url, response.status]
    );

    res.json({ delivered: true, status: response.status });
  } catch (err) {
    res.status(502).json({ error: 'delivery failed' });
  }
});

// Admin data export - uses user-supplied column list
app.get('/api/admin/export', requireAuth, async (req, res) => {
  if (req.session.role !== 'admin') return res.status(403).json({ error: 'admin only' });

  const { table, columns, where_clause } = req.query;
  const allowedTables = ['users', 'metrics', 'audit_log'];
  if (!allowedTables.includes(table)) return res.status(400).json({ error: 'invalid table' });

  // columns is validated to only contain word characters and commas
  if (!/^[\w,]+$/.test(columns)) return res.status(400).json({ error: 'invalid columns' });

  const query = `SELECT ${columns} FROM ${table} WHERE ${where_clause}`;
  const result = await pool.query(query);
  res.json(result.rows);
});

app.listen(3000, () => console.log('API server running on :3000'));
